function demoMain(idx,label){
  var blobs=[[0x89,0x50,0x4E,0x47],[0xFF,0xD8,0xFF,0xE0],[0x25,0x50,0x44,0x46]];
  var b=blobs[idx%blobs.length];
  var hex=b.map(function(x){return ("0"+x.toString(16)).slice(-2);}).join(" ");
  var magic={"89 50 4e 47":"PNG","ff d8 ff e0":"JPEG","25 50 44 46":"PDF"}[hex]||"unknown";
  return "["+label+"] bytes: "+hex+" -> magic identifies "+magic;
}

